<script setup lang="ts">import {useAcademyAllocations,type AcademyAllocation} from '~/composables/useAcademyAllocations';definePageMeta({layout:'main',middleware:'auth'});const route=useRoute(),api=useApi();const id=ref(0),courses=ref<any[]>([]),rows=ref<AcademyAllocation[]>([]),meta=ref<any>({}),course=ref<number|null>(null),amount=ref(1),purpose=ref(''),loading=ref(false),message=ref('');const {allocateToCourse,fetchAllocations}=useAcademyAllocations();const load=async(p=1)=>{const r=await fetchAllocations(id.value,{page:p,per_page:10});rows.value=r.data;meta.value=r.meta};onMounted(async()=>{const a:any=await api.get(`/api/academies/${route.params.name}`);id.value=a.academy?.id||a.data?.id||a.id;const c:any=await api.get(`/api/academies/${id.value}/courses?per_page=100`);courses.value=c.courses?.data||c.courses||c.data||[];await load()});const submit=async()=>{if(!course.value||amount.value<1)return;loading.value=true;try{await allocateToCourse(id.value,{course_id:course.value,amount:amount.value,purpose:purpose.value||undefined});message.value='Allocation completed';course.value=null;amount.value=1;purpose.value='';await load()}finally{loading.value=false}}</script>
<template><div class="mx-auto max-w-7xl space-y-6 p-6"><nav class="text-sm text-slate-500">Academies → {{route.params.name}} → Admin → Allocations</nav><div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl bg-white p-6 shadow"><h1 class="mb-4 text-xl font-bold">Transfer to a course</h1><select v-model="course" class="mb-3 w-full rounded border p-3"><option :value="null">Select course</option><option v-for="c in courses" :key="c.id" :value="c.id">{{c.name}}</option></select><input v-model.number="amount" type="number" min="1" step="1" class="mb-1 w-full rounded border p-3" placeholder="Points amount"><p class="mb-3 text-xs text-slate-500">Enter a whole-number point amount.</p><textarea v-model="purpose" maxlength="500" class="mb-3 w-full rounded border p-3" placeholder="Purpose (max 500 characters)"/><button :disabled="loading" class="w-full rounded bg-primary-600 p-3 text-white" @click="submit">Transfer</button><p class="mt-3 text-emerald-600">{{message}}</p></section><section class="rounded-2xl bg-white p-6 shadow"><h2 class="mb-4 text-xl font-bold">History</h2><table class="w-full text-left text-sm"><thead><tr><th>Date</th><th>Course</th><th>Amount</th><th>Purpose</th><th>Performer</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" class="border-t"><td class="py-3">{{new Date(r.created_at).toLocaleDateString()}}</td><td>{{r.course?.name||r.course_id}}</td><td>{{r.amount}}</td><td class="max-w-[8rem] truncate">{{r.purpose||'—'}}</td><td>{{r.performer?.name||'—'}}</td></tr></tbody></table><div class="mt-4 flex justify-center gap-4"><button v-if="meta.current_page>1" @click="load(meta.current_page-1)">Previous</button><span>{{meta.current_page||1}}</span><button v-if="meta.current_page<meta.last_page" @click="load(meta.current_page+1)">Next</button></div></section></div></div></template>
